using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.EventSystems;
using UnityEditor;
using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class GridShiftUwbChecks {
 static GridShiftUwbChecks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("UwbChecks",false)){SessionState.SetBool("UwbChecks",false);new GameObject("UwbIntegrationChecks").AddComponent<GridShiftUwbPlayChecks>();}};}
 public static void Batch(){EditorSceneManager.OpenScene("Assets/Scenes/Office.unity");foreach(var w in UnityEngine.Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))w.enabled=false;SessionState.SetBool("UwbChecks",true);EditorApplication.isPlaying=true;}
}
public class GridShiftUwbPlayChecks:MonoBehaviour {
 [Serializable]public class State{public bool present;public float x,y;public string text,href,value,second,active;public int clicks,contexts,drags,enter,start,end,scroll;}
 readonly StringBuilder report=new StringBuilder();readonly List<string> errors=new List<string>();readonly List<InputDevice> disabled=new List<InputDevice>();
 Keyboard keyboard;Mouse mouse;ComputerInteraction terminal;GridShiftUwbTerminal adapter;State state;int queryID;volatile string reply,expected;string loadedUrl,clipboard;bool loaded;
 void Check(bool ok,string label){if(!ok)throw new Exception(label);report.AppendLine("PASS "+label);}
 void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors.Add(message);}
 IEnumerator Start(){Application.runInBackground=true;Time.timeScale=1;Application.logMessageReceived+=Log;clipboard=GUIUtility.systemCopyBuffer;
  InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;
  foreach(var device in InputSystem.devices.ToArray())if(device is Keyboard||device is Mouse){InputSystem.DisableDevice(device);disabled.Add(device);}keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.onAfterUpdate+=Current;
  var routines=new Stack<IEnumerator>();routines.Push(Run());bool success=true;while(routines.Count>0){object value=null;bool more;try{more=routines.Peek().MoveNext();if(more)value=routines.Peek().Current;}catch(Exception e){success=false;report.AppendLine("FAIL "+e);break;}if(!more){routines.Pop();continue;}if(value is IEnumerator nested&&!(value is CustomYieldInstruction)){routines.Push(nested);continue;}yield return value;}
  InputSystem.onAfterUpdate-=Current;InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);foreach(var device in disabled)if(device.added)InputSystem.EnableDevice(device);GUIUtility.systemCopyBuffer=clipboard;Application.logMessageReceived-=Log;
  report.AppendLine("Erros de execução: "+string.Join("; ",errors));success&=errors.Count==0;report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));File.WriteAllText("uwb-tests.txt",report.ToString());EditorApplication.Exit(success?0:1);
 }
 void Current(){keyboard.MakeCurrent();mouse.MakeCurrent();}
 IEnumerator Until(Func<bool> test,float timeout,string label){float until=Time.realtimeSinceStartup+timeout;while(!test()&&Time.realtimeSinceStartup<until)yield return null;if(!test())throw new Exception("Timeout: "+label);}
 IEnumerator Query(string expression){expected="GRIDSHIFT_CHECK_"+(++queryID)+"|";reply=null;adapter.browser.browserClient.ExecuteJs("document.title='"+expected+"'+JSON.stringify("+expression+");");yield return Until(()=>reply!=null,8,"resposta JavaScript "+queryID);state=JsonUtility.FromJson<State>(reply.Substring(expected.Length));}
 Vector2 ScreenPoint(float x,float y){var rect=adapter.browser.GetComponent<RectTransform>();var bounds=rect.rect;var texture=adapter.browser.browserClient.BrowserTexture;return terminal.playerCamera.WorldToScreenPoint(rect.TransformPoint(new Vector3(bounds.xMin+x/texture.width*bounds.width,bounds.yMax-y/texture.height*bounds.height,0)));}
 IEnumerator Move(Vector2 point,int buttons=0,Vector2 scroll=default){InputSystem.QueueStateEvent(mouse,new MouseState{position=point,buttons=(ushort)buttons,scroll=scroll});yield return null;yield return null;}
 IEnumerator Click(float x,float y,int button=1){var point=ScreenPoint(x,y);yield return Move(point);yield return Move(point,button);yield return Move(point);yield return new WaitForSecondsRealtime(.15f);}
 IEnumerator Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));yield return null;yield return null;}
 IEnumerator Tap(Key key){yield return Keys(key);yield return Keys();yield return new WaitForSecondsRealtime(.1f);}
 IEnumerator Text(string value){foreach(char character in value){InputSystem.QueueTextEvent(keyboard,character);yield return null;}yield return new WaitForSecondsRealtime(.2f);}
 IEnumerator Shortcut(Key key){yield return Keys(Key.LeftCtrl);yield return Keys(Key.LeftCtrl,key);yield return Keys(Key.LeftCtrl);yield return Keys();yield return new WaitForSecondsRealtime(.25f);}
 void Capture(string name){var source=terminal.playerCamera;var go=new GameObject("BrowserCapture");var camera=go.AddComponent<Camera>();camera.CopyFrom(source);camera.enabled=false;camera.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);var rt=new RenderTexture(1920,1080,24);camera.targetTexture=rt;Canvas.ForceUpdateCanvases();camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();Directory.CreateDirectory("uwb-images");File.WriteAllBytes("uwb-images/"+name+".png",image.EncodeToPNG());RenderTexture.active=old;rt.Release();Destroy(rt);Destroy(image);Destroy(go);}
 IEnumerator Run(){yield return new WaitForSecondsRealtime(2);terminal=UnityEngine.Object.FindFirstObjectByType<ComputerInteraction>();adapter=terminal.webView as GridShiftUwbTerminal;Check(adapter!=null,"Office vincula o UWB instalado ao computador existente");
  var client=adapter.browser.browserClient;client.OnTitleChange+=value=>{if(expected!=null&&value.StartsWith(expected))reply=value;};client.OnLoadFinish+=url=>{loadedUrl=url;loaded=true;};
  var cameraPosition=terminal.playerCamera.transform.localPosition;var cameraRotation=terminal.playerCamera.transform.localRotation;float fov=terminal.playerCamera.fieldOfView;
  terminal.EnterComputer();yield return Until(()=>!terminal.MovingCamera&&adapter.inputRouter.Ready&&adapter.inputRouter.Focused,45,"Chromium inicializado");yield return Until(()=>loaded&&loadedUrl.StartsWith("https://urbanlink-flow.onrender.com"),60,"site real carregado");yield return new WaitForSecondsRealtime(1);
  var size=client.BrowserTexture;Check(size.width==adapter.TargetResolution().x&&size.height==adapter.TargetResolution().y,"textura real do Chromium: "+size.width+"x"+size.height);Check(terminal.playerMovement.ControlsBlocked,"controles do jogador bloqueados enquanto usa o PC");Check(UnityEngine.Object.FindObjectsByType<EventSystem>(FindObjectsSortMode.None).Count(e=>e.isActiveAndEnabled)==1,"um único EventSystem ativo");
  for(int x=1;x<=3;x++)for(int y=1;y<=3;y++){var expectedPixel=new Vector2(size.width*x/4f,size.height*y/4f);Check(adapter.inputRouter.Map(ScreenPoint(expectedPixel.x,expectedPixel.y),out var actual)&&Vector2.Distance(actual,expectedPixel)<2,"mapeamento cursor/textura "+x+","+y);}
  float contentDeadline=Time.realtimeSinceStartup+45;do{yield return Query("({text:document.body.innerText.slice(0,1500),href:location.href})");if(state.text.Contains("cidade")||state.text.Contains("UrbanLink"))break;yield return new WaitForSecondsRealtime(1);}while(Time.realtimeSinceStartup<contentDeadline);
  report.AppendLine("INFO site "+state.href+"; conteúdo="+state.text);Capture("urbanlink-monitor");Check(state.text.Contains("cidade")||state.text.Contains("UrbanLink"),"conteúdo HTML do UrbanLink Flow real recebido");
  yield return Query("(()=>{let a=[...document.querySelectorAll('a,button')].find(e=>e.innerText.includes('Acessar'));if(!a)return {present:false};let r=a.getBoundingClientRect();return {present:true,x:(r.x+r.width/2)*devicePixelRatio,y:(r.y+r.height/2)*devicePixelRatio,href:a.href||''}})()");Check(state.present,"botão real Acessar localizado");string destination=state.href;yield return Click(state.x,state.y);yield return new WaitForSecondsRealtime(2);yield return Query("({href:location.href,text:document.body.innerText.slice(0,1500)})");Check(state.href==destination||state.text.Contains("Entrar")||state.text.Contains("Login"),"clique pelo EventSystem navegou no site real");Capture("urbanlink-navigation");
  adapter.pageZoom=100;adapter.ApplyZoom();yield return new WaitForSecondsRealtime(1);var originalResolution=adapter.resolution;bool originalAspect=adapter.matchMonitorAspect;adapter.matchMonitorAspect=false;
  foreach(var resolution in new[]{new Vector2Int(1600,900),new Vector2Int(1920,1080)}){adapter.resolution=resolution;adapter.ApplyResolution();yield return new WaitForSecondsRealtime(.8f);Canvas.ForceUpdateCanvases();yield return Query("({x:innerWidth,y:innerHeight})");var bounds=adapter.browser.GetComponent<RectTransform>().rect;Check(client.BrowserTexture.width==resolution.x&&client.BrowserTexture.height==resolution.y&&Mathf.Abs(state.x-resolution.x)<2&&Mathf.Abs(state.y-resolution.y)<2,"redimensionamento real textura/viewport CEF "+resolution);Check(Mathf.Abs(bounds.width/bounds.height-resolution.x/(float)resolution.y)<.01f,"proporção preservada em "+resolution);}
  adapter.resolution=originalResolution;adapter.matchMonitorAspect=originalAspect;adapter.ApplyResolution();yield return new WaitForSecondsRealtime(.8f);
  loaded=false;client.LoadHtml("<!doctype html><html><head><meta charset='utf-8'><style>body{margin:0;background:#142030;color:white;font:28px Arial;height:3500px}button,input{position:absolute;left:80px;width:620px;height:80px;font:28px Arial}button{top:100px}#first{top:250px}#second{top:360px}#drag{position:absolute;left:850px;top:100px;width:400px;height:300px;background:#bc9c20}</style></head><body><button id='button' onclick='clicks++'>Teste de clique</button><input id='first'><input id='second'><div id='drag'>Arraste</div><script>window.clicks=0;window.contexts=0;window.drags=0;window.enters=0;document.addEventListener('contextmenu',e=>{e.preventDefault();contexts++});document.addEventListener('mousemove',e=>{if(e.buttons===1)drags++});document.addEventListener('keydown',e=>{if(e.key==='Enter'){enters++;e.preventDefault()}});</script></body></html>");yield return new WaitForSecondsRealtime(.8f);
  yield return Click(160,140);yield return Click(550,140);yield return Click(320,140,2);yield return Query("({clicks:clicks,contexts:contexts})");Check(state.clicks==2&&state.contexts==1,"cliques esquerdo/direito em posições diferentes chegaram ao Chromium");
  yield return Move(ScreenPoint(900,180),1);yield return Move(ScreenPoint(1150,300),1);yield return Move(ScreenPoint(1150,300));yield return Query("({drags:drags})");Check(state.drags>0,"arraste manteve botão pressionado no Chromium");
  yield return Click(220,290);yield return Text("GridShift42");yield return Query("({value:document.getElementById('first').value})");Check(state.value=="GridShift42","digitação de letras e números pelo novo Input System");yield return Tap(Key.Backspace);yield return Query("({value:document.getElementById('first').value})");Check(state.value=="GridShift4","Backspace funcional");yield return Shortcut(Key.A);yield return Query("({start:first.selectionStart,end:first.selectionEnd,value:first.value})");Check(state.start==0&&state.end==state.value.Length,"Ctrl+A seleciona texto");yield return Shortcut(Key.C);yield return Click(220,400);yield return Shortcut(Key.V);yield return Query("({second:second.value})");Check(state.second=="GridShift4","Ctrl+C e Ctrl+V usando clipboard real do Chromium");
  yield return Click(200,290);yield return Tap(Key.Tab);yield return Query("({active:document.activeElement.id})");Check(state.active=="second","Tab muda campo de texto");yield return Tap(Key.Enter);yield return Query("({enter:enters})");Check(state.enter>0,"Enter chegou ao campo");
  yield return Move(new Vector2(5,5));yield return Text("ABC ação");yield return Query("({second:second.value})");Check(state.second.EndsWith("ABC ação"),"foco e texto acentuado mantidos quando o mouse sai da tela");
  var playerPosition=terminal.player.position;yield return Keys(Key.E,Key.W,Key.LeftShift,Key.Space);yield return new WaitForSecondsRealtime(.2f);yield return Keys();Check(terminal.UsingComputer&&terminal.gameObject.scene==UnityEngine.SceneManagement.SceneManager.GetActiveScene()&&Vector3.Distance(playerPosition,terminal.player.position)<.001f,"E/W/Shift/Espaço não acionam porta, movimento ou pulo durante o uso");
  yield return Move(ScreenPoint(700,700),0,new Vector2(0,-120));yield return Move(ScreenPoint(700,700));yield return new WaitForSecondsRealtime(.3f);yield return Query("({scroll:Math.round(scrollY)})");Check(state.scroll>20,"scroll do novo Input System chegou ao Chromium");
  yield return Tap(Key.Escape);yield return Until(()=>!terminal.MovingCamera,5,"saída do computador");Check(!terminal.UsingComputer&&!adapter.inputRouter.Focused&&!terminal.playerMovement.ControlsBlocked&&!PauseMenu.Instance.IsOpen,"ESC libera navegador e jogador sem abrir pausa");Check(Vector3.Distance(cameraPosition,terminal.playerCamera.transform.localPosition)<.001f&&Quaternion.Angle(cameraRotation,terminal.playerCamera.transform.localRotation)<.01f&&Mathf.Abs(fov-terminal.playerCamera.fieldOfView)<.01f,"animação restaura posição, rotação e FOV originais");
  yield return Text("NAO_ENTRAR");yield return Query("({second:second.value})");Check(!state.second.Contains("NAO_ENTRAR"),"teclado não é capturado após sair");
  for(int i=0;i<2;i++){terminal.EnterComputer();yield return Until(()=>!terminal.MovingCamera&&adapter.inputRouter.Focused,6,"reentrada no PC");terminal.ExitComputer();yield return Until(()=>!terminal.MovingCamera,5,"saída repetida");Check(!adapter.inputRouter.Focused&&!terminal.playerMovement.ControlsBlocked,"reentrada e saída preservam foco/controles "+i);}
 }
}


